package creational.builder.sample.step;

public class Main {

    public static void main(String[] args) {

        Pizza pizza = PizzaBuilder.builder()
                .setSize("Large")
                .setCrust("Thin")
                .addCheese()
                .addTopping("Olives")
                .addTopping("Mushroom")
                .build();

        pizza.showPizza(); 
    }
}

package creational.builder.sample.step;

import java.util.List;

public class Pizza {
    private final String size;
    private final String crust;
    private final boolean cheese;
    private final List<String> toppings;

    Pizza(String size, String crust, boolean cheese, List<String> toppings) {
        this.size = size;
        this.crust = crust;
        this.cheese = cheese;
        this.toppings = toppings;
    }

    public void showPizza() {
        System.out.println("Pizza Details:");
        System.out.println("Size: " + size);
        System.out.println("Crust: " + crust);
        System.out.println("Cheese: " + cheese);
        System.out.println("Toppings: " + toppings);
    }
}

package creational.builder.sample.step;

import java.util.ArrayList;
import java.util.List;

public class PizzaBuilder implements ISizeStep, ICrustStep, IOptionalStep {
    private String size;
    private String crust;
    private boolean cheese;
    private final List<String> toppings = new ArrayList<>();

    public static ISizeStep builder() {
        return new PizzaBuilder();
    }

    @Override
    public ICrustStep setSize(String size) {
        this.size = size;
        return this;
    }

    @Override
    public IOptionalStep setCrust(String crust) {
        this.crust = crust;
        return this;
    }

    @Override
    public IOptionalStep addCheese() {
        this.cheese = true;
        return this;
    }

    @Override
    public IOptionalStep addTopping(String topping) {
        toppings.add(topping);
        return this;
    }

    @Override
    public Pizza build() {
        return new Pizza(size, crust, cheese, new ArrayList<>(toppings));
    }
}

